bool is_land_collision_event(std::string_view event) {
    return event == "land_collision_start" || event == "land_collision" || event == "land_collision_end";
}

bool numeric(Type type) {
    return type == Type::Integer || type == Type::Float;
}

struct Token {
    Kind kind;
    std::string text;
    std::int32_t integer = 0;
    std::size_t line = 1, column = 1;
    double real = 0;
};

struct CompileFailure {
    LslDiagnostic diagnostic;
};

[[noreturn]] void fail(const Token &t, std::string message) {
    throw CompileFailure{{t.line, t.column, std::move(message)}};
}

std::size_t utf16_length(std::string_view text) {
    std::size_t n = 0;
    for (unsigned char c : text)
        if ((c & 0xc0) != 0x80)
            n += c >= 0xf0 ? 2 : 1;
    return n;
}

class Lexer {
    std::string_view source;
    std::size_t pos = 0, line = 1, column = 1;
    bool character_option = false;
    bool advanced_flow_option = false;
    bool array_option = false;

    char take() {
        char c = source[pos++];
        if (c == '\n') {
            line++;
            column = 1;
        } else {
            // Asset text reaches the lexer as valid UTF-8 after SDK-compatible
            // decoding. Original C# source columns count UTF-16 code units;
            // keep the byte cursor/literal bytes intact and count only leaders.
            // Low-level callers retain permissive byte parsing, with no new
            // rejection or source/program-hash normalization here.
            const auto byte = static_cast<unsigned char>(c);
            if ((byte & 0xc0u) != 0x80u)
                column += byte >= 0xf0u && byte <= 0xf4u ? 2 : 1;
        }
        return c;
    }

    bool float_token(Token &token) {
        // Match original TokenBegin.TryParseFloat operation by operation. Its
        // repeated decimal scaling can differ by an ULP from nearest parsing,
        // and those same bits participate in the original token source hash.
        auto cursor = pos - 1;
        std::uint64_t mantissa = 0;
        std::int32_t exponent = 0;
        bool decimals = false;
        const auto add = [](std::int32_t a, std::int32_t b) {
            return std::bit_cast<std::int32_t>(std::bit_cast<std::uint32_t>(a) + std::bit_cast<std::uint32_t>(b));
        };
        const auto subtract = [](std::int32_t a, std::int32_t b) {
            return std::bit_cast<std::int32_t>(std::bit_cast<std::uint32_t>(a) - std::bit_cast<std::uint32_t>(b));
        };
        for (; cursor < source.size(); ++cursor) {
            char c = source[cursor];
            if (c >= '0' && c <= '9') {
                const auto next = mantissa * 10 + static_cast<unsigned>(c - '0');
                if (next / 10 != mantissa) {
                    if (!decimals)
                        exponent = add(exponent, 1);
                } else {
                    mantissa = next;
                    if (decimals)
                        exponent = subtract(exponent, 1);
                }
                continue;
            }
            if (c == '.') {
                if (decimals)
                    fail(token, "more than one decimal point");
                decimals = true;
                continue;
            }
            if (c == 'e' || c == 'E') {
                if (++cursor == source.size())
                    fail(token, "floating exponent off end of source");
                c = source[cursor];
                const bool negative = c == '-';
                if (negative || c == '+')
                    ++cursor;
                std::int32_t magnitude = 0;
                bool empty = true;
                for (; cursor < source.size(); ++cursor) {
                    c = source[cursor];
                    if (c < '0' || c > '9')
                        break;
                    const auto next = std::bit_cast<std::int32_t>(std::bit_cast<std::uint32_t>(magnitude) * 10 +
                                                                  static_cast<unsigned>(c - '0'));
                    if (next / 10 != magnitude)
                        fail(token, "floating exponent overflow");
                    magnitude = next;
                    empty = false;
                }
                if (empty)
                    fail(token, "bad or missing floating exponent");
                const auto combined = negative ? subtract(exponent, magnitude) : add(exponent, magnitude);
                if (negative ? combined > exponent : combined < exponent)
                    fail(token, "floating exponent overflow");
                exponent = combined;
            }
            if (c == 'f' || c == 'F') {
                if (++cursor == source.size())
                    fail(token, "f at end of source");
                c = source[cursor];
                if ((c >= '0' && c <= '9') || c == '.' || c == 'e' || c == 'E' || c == 'f' || c == 'F')
                    fail(token, "Syntax error");
            }
            break;
        }
        if (!decimals)
            return false;
        // Force IEEE binary64 rounding at each original CLR arithmetic step,
        // including on hosts whose compiler could otherwise retain excess precision.
        // Original CLR conv.r.un for UInt64 uses a signed conversion followed
        // by adding 2^64 when the high bit is set. Preserve both rounding steps:
        // a native unsigned cast can produce a different source-token value.
        volatile double value = static_cast<double>(std::bit_cast<std::int64_t>(mantissa));
        if (mantissa & (std::uint64_t{1} << 63))
            value = value + 18446744073709551616.0;
        if (exponent && mantissa) {
            volatile double scale = 10.;
            const bool negative = exponent < 0;
            if (negative)
                exponent = subtract(0, exponent);
            while (exponent > 0) {
                if (exponent & 1) {
                    if (negative)
                        value = value / scale;
                    else
                        value = value * scale;
                }
                exponent /= 2;
                scale = scale * scale;
            }
        }
        token.kind = Kind::Float;
        token.real = value;
        while (pos < cursor)
            take();
        return true;
    }

  public:
    explicit Lexer(std::string_view s) : source(s) {}

    bool arrays_enabled() const {
        return array_option;
    }

    bool chars_enabled() const {
        return character_option;
    }

    bool advanced_flow_enabled() const {
        return advanced_flow_option;
    }

    Token next() {
        for (;;) {
            while (pos < source.size() && static_cast<unsigned char>(source[pos]) <= 32)
                take();
            if (source.substr(pos, 2) == "//") {
                while (pos < source.size() && take() != '\n') {
                }
                continue;
            }
            if (source.substr(pos, 2) == "/*") {
                take();
                take();
                while (pos < source.size() && source.substr(pos, 2) != "*/")
                    take();
                if (pos < source.size()) {
                    take();
                    take();
                }
                continue;
            }
            break;
        }
        Token t{Kind::End, "", 0, line, column};
        if (pos == source.size())
            return t;
        char c = take();
        if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || c == '_') {
            t.kind = Kind::Name;
            t.text += c;
            while (pos < source.size()) {
                c = source[pos];
                if (!((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_'))
                    break;
                t.text += take();
            }
            if (t.text.size() > 255)
                fail(t, "name too long, max 255");
            auto option_keyword = t.text;
            for (auto &unit : option_keyword)
                if (unit >= 'A' && unit <= 'Z')
                    unit += 'a' - 'A';
            if (option_keyword == "yoption") {
                const auto option = next();
                auto name = option.text;
                for (auto &unit : name)
                    if (unit >= 'A' && unit <= 'Z')
                        unit += 'a' - 'A';
                if (option.kind != Kind::Name || next().text != ";")
                    fail(t, "invalid YOption declaration");
                if (name == "arrays" || name == "allowall")
                    array_option = true;
                if (name == "chars" || name == "allowall")
                    character_option = true;
                if (name == "advflowctl" || name == "allowall")
                    advanced_flow_option = true;
                else if (name != "chars" && name != "arrays" && name != "trycatch" && name != "objects" &&
                         name != "norighttoleft" && name != "dollarsigns")
                    fail(option, "unknown YOption");
                return next();
            }
            if (option_keyword == "yoptions") {
                if (next().text != ";")
                    fail(t, "invalid YOptions declaration");
                advanced_flow_option = true;
                return next();
            }
            return t;
        }
        if (c == '\'') {
            t.kind = Kind::Character;
            bool escaped = false, closed = false;
            std::string contents;
            while (pos < source.size()) {
                c = take();
                if (c == '\\' && !escaped) {
                    escaped = true;
                    continue;
                }
                if (c == '\'' && !escaped) {
                    closed = true;
                    break;
                }
                contents += escaped && c == 'n' ? '\n' : escaped && c == 't' ? '\t' : c;
                escaped = false;
            }
            const auto units = framework::utf16_replacing(contents);
            if (!closed || units.size() != 1)
                fail(t, "character must be exactly one character");
            t.integer = units.front();
            t.text = std::move(contents);
            return t;
        }
        if ((c >= '0' && c <= '9') || c == '.') {
            if (c == '.' && source.substr(pos, 2) == "..") {
                take();
                take();
                t.kind = Kind::Symbol;
                t.text = "...";
                return t;
            }
            if ((c >= '0' && c <= '9') || (c == '.' && pos < source.size() && source[pos] >= '0' && source[pos] <= '9'))
                if (float_token(t))
                    return t;
        }
        if (c >= '0' && c <= '9') {
            t.kind = Kind::Integer;
            std::uint32_t value = c - '0', base = 10;
            if (c == '0' && pos < source.size() && (source[pos] == 'x' || source[pos] == 'X')) {
                take();
                base = 16;
                value = 0;
            }
            while (pos < source.size()) {
                unsigned char d = source[pos];
                if ((d == 'x' || d == 'X') && value == 0 && base == 10) {
                    take();
                    base = 16;
                    continue;
                }
                unsigned n = d >= '0' && d <= '9'   ? d - '0'
                             : d >= 'a' && d <= 'f' ? d - 'a' + 10
                             : d >= 'A' && d <= 'F' ? d - 'A' + 10
                                                    : 99;
                if (n >= base)
                    break;
                take();
                auto v = std::uint64_t(value) * base + n;
                if (v > 0xffffffffull)
                    fail(t, "integer overflow");
                value = static_cast<std::uint32_t>(v);
            }
            t.integer = std::bit_cast<std::int32_t>(value);
            return t;
        }
        if (c == '"') {
            t.kind = Kind::String;
            auto begin = pos - 1;
            bool escaped = false, closed = false;
            while (pos < source.size()) {
                c = take();
                if (c == '\\' && !escaped) {
                    escaped = true;
                    continue;
                }
                if (c == '"' && !escaped) {
                    closed = true;
                    break;
                }
                if (escaped && c == 'n')
                    t.text += '\n';
                else if (escaped && c == 't')
                    t.text += "    ";
                else
                    t.text += c;
                escaped = false;
            }
            if (!closed)
                fail(t, "unterminated string");
            if (utf16_length(source.substr(begin, pos - begin - 1)) > 4096)
                fail(t, "string too long, max 4096");
            return t;
        }
        if ((c == '&' || c == '|') && pos < source.size() && source[pos] == c) {
            t.kind = Kind::Symbol;
            t.text += c;
            t.text += take();
            if (pos < source.size() && source[pos] == c)
                t.text += take();
            return t;
        }
        if (std::string_view("{}[](),;:+-<>*/%=!&|^~@.?").find(c) != std::string_view::npos) {
            t.kind = Kind::Symbol;
            t.text += c;
            if (std::string_view("<>+-").find(c) != std::string_view::npos && pos < source.size() && source[pos] == c)
                t.text += take();
            const bool shift = t.text == "<<" || t.text == ">>";
            if ((shift || (t.text.size() == 1 && std::string_view("<>=!+-*/%&|^").find(c) != std::string_view::npos)) &&
                pos < source.size() && source[pos] == '=')
                t.text += take();
            return t;
        }
        fail(t, "unsupported token in native LSL subset");
    }
};

