bool is_drawing_function(std::string_view name) {
    return name.starts_with("os") &&
           std::ranges::any_of(drawing_commands, [name](const auto &command) { return command.function == name; });
}

bool is_environment_query(std::string_view name) {
    return name == "osGetCurrentSunHour" || name == "osGetApparentTime" || name == "osGetApparentRegionTime" ||
           name == "osGetApparentTimeString" || name == "osGetApparentRegionTimeString" || name == "osGetSunParam" ||
           name == "osSunGetParam";
}
