bool writable(const Expression &e) {
    return e.op == Expression::Op::Local || e.op == Expression::Op::ScriptArrayElement ||
           e.op == Expression::Op::ScriptClassField ||
           (e.op == Expression::Op::Component && e.left->op == Expression::Op::Local);
}

std::unique_ptr<Expression> copy_target(const Expression &e) {
    auto copy = std::make_unique<Expression>();
    copy->location = e.location;
    copy->op = e.op;
    copy->type = e.type;
    copy->script_type = e.script_type;
    copy->height = e.height;
    copy->slot = e.slot;
    copy->global = e.global;
    if (e.left)
        copy->left = copy_target(*e.left);
    return copy;
}

std::optional<Type> spatial_binary_type(Expression::Op op, Type left, Type right) {
    using Op = Expression::Op;
    if (left == Type::Character && right == Type::Integer && (op == Op::Add || op == Op::Subtract))
        return Type::Character;
    if (left == Type::Character && right == Type::Character &&
        (op == Op::Subtract || op == Op::Equal || op == Op::NotEqual || op == Op::Less || op == Op::LessEqual ||
         op == Op::Greater || op == Op::GreaterEqual))
        return Type::Integer;
    if (left == Type::Vector && right == Type::Rotation && (op == Op::Multiply || op == Op::Divide))
        return Type::Vector;
    if (left == Type::Rotation && right == Type::Rotation) {
        if (op == Op::Equal || op == Op::NotEqual)
            return Type::Integer;
        if (op == Op::Add || op == Op::Subtract || op == Op::Multiply || op == Op::Divide)
            return Type::Rotation;
    }
    if (left == Type::Vector && right == Type::Vector) {
        if (op == Op::Add || op == Op::Subtract || op == Op::Remainder)
            return Type::Vector;
        if (op == Op::Multiply)
            return Type::Float;
        if (op == Op::Equal || op == Op::NotEqual)
            return Type::Integer;
    } else if ((left == Type::Vector && numeric(right)) || (right == Type::Vector && numeric(left))) {
        if (op == Op::Multiply || (op == Op::Divide && left == Type::Vector))
            return Type::Vector;
    }
    return {};
}

LslValue default_value(Type type) {
    switch (type) {
    case Type::Object:
    case Type::ScriptClass:
        return LslNullObject{};
    case Type::Integer:
    case Type::Void:
        return std::int32_t{0};
    case Type::Float:
        return 0.;
    case Type::Character:
        return LslCharacter{};
    case Type::Rotation:
        return LslRotation{};
    case Type::Vector:
        return framework::Vector3d{};
    case Type::List:
        return std::make_shared<const LslList>();
    default:
        return std::string{};
    }
}

LslValue constructor_storage_value(Type type) {
    // CLR reference arrays are zero-filled before source-order declaration
    // stores run. Keep normal local/declaration defaults in default_value.
    if (type == Type::String || type == Type::Key)
        return LslNullString{};
    if (type == Type::List)
        return LslNullList{};
    if (type == Type::Rotation)
        return LslRotation{0., 0., 0., 0.};
    return default_value(type);
}

