std::uint64_t source_frame_bytes(const Handler &handler) {
    if (!handler.complex)
        return 0;
    std::uint64_t bytes = 64;
    for (const auto type : handler.local_types) {
        switch (type) {
        case Type::Character:
            bytes += 1; // Marshal.SizeOf(System.Char), used by original frame accounting.
            break;
        case Type::Integer:
            bytes += 4;
            break;
        case Type::Vector:
            bytes += 24;
            break;
        case Type::Rotation:
            bytes += 32;
            break;
        default:
            bytes += 8;
            break;
        }
    }
    return bytes;
}

std::int32_t wrap(std::uint32_t n) {
    return std::bit_cast<std::int32_t>(n);
}

std::optional<std::int32_t> constant_character_input(const Expression &expression) {
    using Op = Expression::Op;
    if (expression.op == Op::Literal && (expression.type == Type::Integer || expression.type == Type::Character))
        return character_integer(expression.value);
    if (expression.left && (expression.op == Op::Negate || expression.op == Op::Not || expression.op == Op::BitNot)) {
        if (const auto value = constant_character_input(*expression.left)) {
            if (expression.op == Op::Not)
                return std::int32_t(!*value);
            return wrap(expression.op == Op::Negate ? 0u - static_cast<std::uint32_t>(*value)
                                                    : ~static_cast<std::uint32_t>(*value));
        }
    }
    if (!expression.left || !expression.right || expression.type != Type::Integer)
        return {};
    const auto left = constant_character_input(*expression.left);
    const auto right = constant_character_input(*expression.right);
    if (!left || !right)
        return {};
    const auto x = static_cast<std::uint32_t>(*left), y = static_cast<std::uint32_t>(*right);
    switch (expression.op) {
    case Op::Add:
        return wrap(x + y);
    case Op::Subtract:
        return wrap(x - y);
    case Op::Multiply:
        return wrap(x * y);
    case Op::BitAnd:
        return wrap(x & y);
    case Op::BitOr:
        return wrap(x | y);
    case Op::BitXor:
        return wrap(x ^ y);
    case Op::Equal:
        return std::int32_t(*left == *right);
    case Op::NotEqual:
        return std::int32_t(*left != *right);
    case Op::Less:
        return std::int32_t(*left < *right);
    case Op::LessEqual:
        return std::int32_t(*left <= *right);
    case Op::Greater:
        return std::int32_t(*left > *right);
    case Op::GreaterEqual:
        return std::int32_t(*left >= *right);
    default:
        return {};
    }
}

std::string utc_text(std::int64_t ticks, bool timestamp) {
    using namespace std::chrono;
    using Ticks = duration<std::int64_t, std::ratio<1, 10000000>>;
    const sys_time<Ticks> instant{Ticks{ticks - 621355968000000000LL}};
    const auto day = floor<days>(instant);
    const year_month_day date{day};
    const hh_mm_ss time{instant - day};
    char result[40];
    std::snprintf(result, sizeof result, "%04d-%02u-%02u", int(date.year()), unsigned(date.month()),
                  unsigned(date.day()));
    if (timestamp) {
        std::snprintf(result + 10, sizeof result - 10, "T%02d:%02d:%02d.%07dZ", int(time.hours().count()),
                      int(time.minutes().count()), int(time.seconds().count()), int(time.subseconds().count()));
    }
    return result;
}

std::string archive_creation_text(std::int32_t seconds, bool date_requested) {
    using namespace std::chrono;
    const sys_seconds instant{std::chrono::seconds{seconds}};
    const auto day = floor<days>(instant);
    char result[48];
    if (date_requested) {
        constexpr std::array weekdays{"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};
        constexpr std::array months{"January", "February", "March",     "April",   "May",      "June",
                                    "July",    "August",   "September", "October", "November", "December"};
        const year_month_day date{day};
        std::snprintf(result, sizeof result, "%s, %02u %s %04d", weekdays[weekday{day}.c_encoding()],
                      unsigned(date.day()), months[unsigned(date.month()) - 1], int(date.year()));
    } else {
        const hh_mm_ss time{instant - day};
        std::snprintf(result, sizeof result, "%02d:%02d:%02d", int(time.hours().count()), int(time.minutes().count()),
                      int(time.seconds().count()));
    }
    return result;
}

std::uint64_t process_resident_bytes() {
#ifdef _WIN32
    PROCESS_MEMORY_COUNTERS counters{};
    return K32GetProcessMemoryInfo(GetCurrentProcess(), &counters, sizeof(counters)) ? counters.WorkingSetSize : 0;
#elif defined(__APPLE__)
    mach_task_basic_info_data_t info{};
    mach_msg_type_number_t count = MACH_TASK_BASIC_INFO_COUNT;
    return task_info(mach_task_self(), MACH_TASK_BASIC_INFO, reinterpret_cast<task_info_t>(&info), &count) ==
                   KERN_SUCCESS
               ? info.resident_size
               : 0;
#elif defined(__linux__)
    std::ifstream statm("/proc/self/statm");
    std::uint64_t total_pages = 0, resident_pages = 0;
    const auto page_size = sysconf(_SC_PAGESIZE);
    if (page_size > 0 && statm >> total_pages >> resident_pages)
        return resident_pages * static_cast<std::uint64_t>(page_size);
    return 0;
#else
    return 0;
#endif
}

double seconds_of_day(std::int64_t ticks, bool local) {
    using namespace std::chrono;
    using Ticks = duration<std::int64_t, std::ratio<1, 10000000>>;
    const sys_time<Ticks> instant{Ticks{ticks - 621355968000000000LL}};
    if (!local)
        return duration<double>(instant - floor<days>(instant)).count();

    const auto whole = floor<seconds>(instant);
    const auto epoch = static_cast<std::time_t>(whole.time_since_epoch().count());
    std::tm time{};
#ifdef _WIN32
    if (localtime_s(&time, &epoch) != 0)
        throw std::runtime_error("LSL local time is out of range");
#else
    if (!localtime_r(&epoch, &time))
        throw std::runtime_error("LSL local time is out of range");
#endif
    return time.tm_hour * 3600 + time.tm_min * 60 + time.tm_sec + duration<double>(instant - whole).count();
}

std::int64_t ticks();

framework::DotnetRegexNodeText regex_text(std::u16string_view text) {
    return std::make_shared<const std::u16string>(text);
}

std::optional<std::int32_t> regex_start(std::size_t length, std::int32_t start) {
    if (length > static_cast<std::size_t>(std::numeric_limits<std::int32_t>::max()))
        return std::nullopt;
    const auto size = static_cast<std::int32_t>(length);
    if (start < 0)
        start += size;
    if (start < 0 || start >= size)
        return std::nullopt;
    return start;
}

LslValue replace_regex(const framework::DotnetRegexNodeText &input, std::u16string_view pattern,
                       std::u16string_view replacement, std::int32_t count, std::int32_t position,
                       std::int32_t options) {
    using namespace framework;
    const auto expression = regex_text(pattern);
    const auto length = static_cast<std::int32_t>(input->size());
    const bool reverse = (options & 64) != 0;
    const auto culture = []() { return std::u16string{}; };
    const auto stack = []() { return sufficient_execution_stack(); };
    auto parsed = dotnet_regex_parse(expression, options, culture, stack);
    const auto rules =
        dotnet_regex_parse_replacement(regex_text(replacement), options, parsed.capture_number_sparse_mapping,
                                       parsed.capture_count, parsed.capture_name_to_number, culture, stack);
    DotnetRegexInterpreter regex(std::move(parsed), expression, stack);

    struct Edit {
        std::int32_t index, length;
        std::u16string text;
    };

    std::vector<Edit> edits;
    int previous = -1;
    for (std::int64_t replaced = 0; count == -1 || replaced < count; ++replaced) {
        const auto match =
            regex.scan(input, 0, length, position, previous, DotnetRegexRunnerMode::FullMatchRequired, 100000);
        if (!match.success)
            break;
        Edit edit{match.index, match.length, {}};
        for (const auto rule : rules.rules) {
            if (rule >= 0) {
                edit.text += *rules.strings.at(rule);
                continue;
            }
            const auto slot = -5 - rule;
            if (slot == -1)
                edit.text.append(*input, 0, match.index);
            else if (slot == -2)
                edit.text.append(*input, match.index + match.length);
            else if (slot == -4)
                edit.text += *input;
            else if (!match.groups.empty()) {
                const auto group = slot == -3 ? match.groups.size() - 1 : static_cast<std::size_t>(slot);
                if (group < match.groups.size() && match.groups[group].success)
                    edit.text.append(*input, match.groups[group].index, match.groups[group].length);
            }
        }
        edits.push_back(std::move(edit));
        position = match.text_position;
        previous = match.length;
    }
    if (reverse)
        std::reverse(edits.begin(), edits.end());
    std::u16string result;
    std::size_t cursor = 0;
    for (const auto &edit : edits) {
        result.append(*input, cursor, edit.index - cursor);
        result += edit.text;
        cursor = static_cast<std::size_t>(edit.index) + edit.length;
    }
    result.append(*input, cursor);
    return make_lsl_string(result);
}

LslValue replace_substring(const std::u16string &source, const std::u16string &pattern,
                           const std::u16string &replacement, std::int32_t count) {
    if (source.empty() || pattern.empty() || count == std::numeric_limits<std::int32_t>::min())
        return make_lsl_string(source);
    try {
        const auto input = regex_text(source);
        if (input->size() > static_cast<std::size_t>(std::numeric_limits<std::int32_t>::max()))
            return make_lsl_string(source);
        const bool reverse = count < 0;
        const auto position = reverse ? static_cast<std::int32_t>(input->size()) : 0;
        return replace_regex(input, pattern, replacement, count == 0 ? -1 : std::abs(count), position,
                             512 | (reverse ? 64 : 0));
    } catch (const std::exception &) {
        return make_lsl_string(source);
    }
}

bool truth(const LslValue &value, Type type) {
    if (std::holds_alternative<LslNullList>(value) || std::holds_alternative<LslNullObject>(value))
        null_string_reference();
    if (is_null_lsl_string(value)) {
        if (type == Type::Key)
            return true;
        null_string_reference();
    }
    if (type == Type::Key) {
        // YEngine TypeCast.KeyToBool tests the source text, rather than
        // parsing it as an SDK UUID. Nonempty malformed keys are also true.
        const auto text = text_units(value);
        return !text.empty() && text != u"00000000-0000-0000-0000-000000000000";
    }
    return std::visit(
        [type](const auto &item) -> bool {
            if constexpr (std::is_same_v<std::decay_t<decltype(item)>, LslBoxedInteger> ||
                          std::is_same_v<std::decay_t<decltype(item)>, LslBoxedFloat>)
                return item.value != 0;
            else if constexpr (std::is_same_v<std::decay_t<decltype(item)>, LslBoxedString> ||
                               std::is_same_v<std::decay_t<decltype(item)>, LslBoxedKey>)
                return !item.value.empty();
            else if constexpr (std::is_same_v<std::decay_t<decltype(item)>, std::string>)
                return !item.empty();
            else if constexpr (std::is_same_v<std::decay_t<decltype(item)>, framework::Vector3d>)
                return item.x != 0 || item.y != 0 || item.z != 0;
            else if constexpr (std::is_same_v<std::decay_t<decltype(item)>, std::shared_ptr<const LslList>>)
                return !item->items.empty();
            else if constexpr (std::is_same_v<std::decay_t<decltype(item)>, LslRotation>)
                return item != LslRotation{};
            else if constexpr (std::is_same_v<std::decay_t<decltype(item)>, LslCharacter>)
                return item.value != 0;
            else if constexpr (std::is_same_v<std::decay_t<decltype(item)>, LslUtf16String> ||
                               std::is_same_v<std::decay_t<decltype(item)>, LslBoxedUtf16String> ||
                               std::is_same_v<std::decay_t<decltype(item)>, LslBoxedUtf16Key>)
                return !item.value.empty();
            else if constexpr (std::is_same_v<std::decay_t<decltype(item)>, LslNullString> ||
                               std::is_same_v<std::decay_t<decltype(item)>, LslBoxedNullString> ||
                               std::is_same_v<std::decay_t<decltype(item)>, LslBoxedNullKey> ||
                               std::is_same_v<std::decay_t<decltype(item)>, LslNullList> ||
                               std::is_same_v<std::decay_t<decltype(item)>, LslNullObject>)
                return (null_string_reference(), false);
            else if constexpr (std::is_same_v<std::decay_t<decltype(item)>, std::shared_ptr<const LslStringReference>>)
                return !item->units.empty();
            else if constexpr (std::is_same_v<std::decay_t<decltype(item)>, std::shared_ptr<const LslObjectBox>>)
                return truth(unbox_lsl_value(item->value), type);
            else if constexpr (std::is_same_v<std::decay_t<decltype(item)>, std::shared_ptr<const LslFixedArray>> ||
                               std::is_same_v<std::decay_t<decltype(item)>, std::shared_ptr<const LslScriptClass>>)
                throw std::runtime_error("InvalidCastException: Specified cast is not valid.");
            else if constexpr (std::is_same_v<std::decay_t<decltype(item)>, LslRawSingle> ||
                               std::is_same_v<std::decay_t<decltype(item)>, LslRawBoolean> ||
                               std::is_same_v<std::decay_t<decltype(item)>, LslRawUuid>)
                throw std::runtime_error("InvalidCastException: Specified cast is not valid.");
            else
                return item != 0;
        },
        value);
}

void append_list_range(LslList &result, const LslList &list, std::int64_t first, std::int64_t last) {
    first = std::max<std::int64_t>(0, first);
    last = std::min(static_cast<std::int64_t>(list.items.size()), last);
    if (first < last)
        result.items.insert(result.items.end(), list.items.begin() + first, list.items.begin() + last);
}

void append_list_slice(LslList &result, const LslList &list, std::int64_t start, std::int64_t end) {
    const auto size = static_cast<std::int64_t>(list.items.size());
    if (start < 0)
        start += size;
    if (end < 0)
        end += size;
    if (start <= end)
        append_list_range(result, list, start, end + 1);
    else if (start < 0)
        append_list_range(result, list, 0, size);
    else {
        append_list_range(result, list, 0, end + 1);
        append_list_range(result, list, start, size);
    }
}

constexpr std::int32_t attachment_message_all = -65535;
constexpr std::int32_t attachment_message_invert = 1;
constexpr std::int32_t attachment_message_object_creator = 2;
constexpr std::int32_t attachment_message_script_creator = 4;

std::optional<std::int32_t> attachment_point_integer(const LslValue &value) {
    if (const auto *number = value_get_if<std::int32_t>(&value))
        return *number;
    const auto string_units = lsl_string_code_units(value);
    const auto string = string_units ? std::optional{framework::utf8(*string_units)} : std::nullopt;
    if (!string)
        return std::nullopt;
    const auto trimmed = framework::trim_utf8(*string);
    std::string_view text(trimmed);
    if (text.starts_with('+')) {
        text.remove_prefix(1);
        if (text.starts_with('-'))
            return std::nullopt;
    }
    std::int32_t point;
    const auto end = text.data() + text.size();
    const auto parsed = std::from_chars(text.data(), end, point);
    if (parsed.ec != std::errc{} || parsed.ptr != end)
        return std::nullopt;
    return point;
}

std::int32_t list_integer(const LslValue &item) {
    if (const auto *box = std::get_if<std::shared_ptr<const LslObjectBox>>(&item))
        return list_integer((*box)->value);
    if (const auto text = raw_clr_text(item))
        return list_integer(make_lsl_string(*text));
    if (const auto *value = value_get_if<std::int32_t>(&item))
        return *value;
    if (const auto *value = value_get_if<double>(&item)) {
        const auto truncated = std::trunc(*value);
        if (!std::isfinite(truncated) || truncated < -2147483648. || truncated >= 2147483648.)
            return std::numeric_limits<std::int32_t>::min();
        return static_cast<std::int32_t>(truncated);
    }
    const auto item_units = lsl_string_code_units(item);
    const auto text = item_units ? std::optional{framework::utf8(*item_units)} : std::nullopt;
    if (!text)
        return 0;
    std::string_view digits = *text;
    const auto start = digits.find_first_not_of(' ');
    if (start == digits.npos)
        return 0;
    digits.remove_prefix(start);
    const bool hex = digits.starts_with("0x") || digits.starts_with("0X");
    const bool negative = digits.starts_with("-");
    if (hex)
        digits.remove_prefix(2);
    else if (negative || digits.starts_with("+"))
        digits.remove_prefix(1);
    std::uint32_t number = 0;
    const auto parsed = std::from_chars(digits.data(), digits.data() + digits.size(), number, hex ? 16 : 10);
    if (parsed.ec == std::errc::result_out_of_range || (!hex && number > 2147483647u))
        return -1;
    if (parsed.ec != std::errc{})
        return 0;
    if (hex)
        return wrap(number);
    return negative ? -static_cast<std::int32_t>(number) : static_cast<std::int32_t>(number);
}

double list_float(const LslValue &item) {
    if (const auto *box = std::get_if<std::shared_ptr<const LslObjectBox>>(&item))
        return list_float((*box)->value);
    if (const auto *single = std::get_if<LslRawSingle>(&item))
        return static_cast<double>(single->value);
    if (const auto *boolean = std::get_if<LslRawBoolean>(&item))
        return boolean->value ? 1. : 0.;
    if (std::holds_alternative<LslRawUuid>(item))
        throw std::runtime_error(
            "InvalidCastException: Unable to cast object of type 'OpenMetaverse.UUID' to type 'System.IConvertible'.");
    if (const auto *value = value_get_if<double>(&item))
        return *value;
    if (const auto *value = value_get_if<std::int32_t>(&item))
        return *value;
    const auto item_units = lsl_string_code_units(item);
    const auto text = item_units ? std::optional{framework::utf8(*item_units)} : std::nullopt;
    if (!text)
        return 0.;
    framework::Uuid key;
    if (framework::try_parse_sdk_uuid(*text, key))
        return list_integer(item);
    const auto units = framework::utf16_replacing(*text);
    std::size_t index = 0;
    while (index < units.size() && framework::unicode_whitespace(units[index]))
        ++index;
    const auto start = index;
    if (index < units.size() && units[index] == u'-')
        ++index;
    if (index < units.size() && units[index] == u'+')
        ++index;
    const auto digit = [](char16_t c) { return c >= u'0' && c <= u'9'; };
    const auto integer_start = index;
    while (index < units.size() && (digit(units[index]) || units[index] == u','))
        ++index;
    if (index == integer_start)
        return 0.;
    if (index < units.size() && units[index] == u'.') {
        ++index;
        while (index < units.size() && digit(units[index]))
            ++index;
    }
    double value = 0.;
    return network::try_parse_invariant_real(framework::utf8(std::u16string_view(units).substr(start, index - start)),
                                             value)
               ? value
               : 0.;
}

framework::Vector3d list_vector(const LslValue &item) {
    if (const auto *box = std::get_if<std::shared_ptr<const LslObjectBox>>(&item))
        return list_vector((*box)->value);
    if (const auto *vector = std::get_if<framework::Vector3d>(&item))
        return *vector;
    const auto item_units = lsl_string_code_units(item);
    const auto text = item_units ? std::optional{framework::utf8(*item_units)} : std::nullopt;
    if (!text || text->size() < 5)
        return {};
    std::string_view input = *text;
    const auto opening = input.find_first_of("<,");
    if (opening == input.npos)
        return {};
    if (input[opening] == '<')
        input.remove_prefix(opening + 1);
    framework::Vector3d result;
    for (auto *component : {&result.x, &result.y}) {
        const auto comma = input.find(',');
        if (comma == input.npos || !network::try_parse_invariant_real(input.substr(0, comma), *component))
            return {};
        input.remove_prefix(comma + 1);
    }
    if (!network::try_parse_invariant_real(input.substr(0, input.find('>')), result.z))
        return {};
    return result;
}

LslRotation list_rotation(const LslValue &item) {
    if (const auto *box = std::get_if<std::shared_ptr<const LslObjectBox>>(&item))
        return list_rotation((*box)->value);
    if (const auto *rotation = std::get_if<LslRotation>(&item))
        return *rotation;
    const auto item_units = lsl_string_code_units(item);
    const auto text = item_units ? std::optional{framework::utf8(*item_units)} : std::nullopt;
    if (!text || framework::utf16(*text).size() < 7)
        return {};
    std::string_view input = *text;
    const auto opening = input.find_first_of("<,");
    if (opening == input.npos)
        return {};
    if (input[opening] == '<')
        input.remove_prefix(opening + 1);
    LslRotation result;
    for (auto *component : {&result.x, &result.y, &result.z}) {
        const auto comma = input.find(',');
        if (comma == input.npos || !network::try_parse_invariant_real(input.substr(0, comma), *component))
            return {};
        input.remove_prefix(comma + 1);
    }
    if (!network::try_parse_invariant_real(input.substr(0, input.find('>')), result.w))
        return {};
    return result;
}

std::optional<LslAvatarName> parse_avatar_name(std::string_view text) {
    const auto name = framework::utf16_replacing(text);
    const auto first_start = name.find_first_not_of(u' ');
    if (first_start == std::u16string::npos)
        return {};
    const auto first_end = name.find_first_of(u" .@", first_start);
    if (first_end == std::u16string::npos || first_end == first_start || name[first_end] == u'@')
        return {};
    const auto first = name.substr(first_start, first_end - first_start);
    auto last_start = name.find_first_not_of(u' ', first_end + 1);
    if (last_start == std::u16string::npos)
        return {};

    const bool first_separator_is_dot = name[first_end] == u'.';
    for (auto index = last_start; index < name.size(); ++index) {
        if (name[index] == u'.') {
            if (first_separator_is_dot || index + 1 == name.size())
                return {};
            last_start = index + 1;
        } else if (name[index] == u'@') {
            const auto server_start = name.find_first_not_of(u' ', index + 1);
            if (server_start == std::u16string::npos || name.size() - server_start < 3)
                return {};
            auto last_end = index;
            while (last_end > last_start && name[last_end - 1] == u' ')
                --last_end;
            if (last_end == last_start)
                return {};
            const auto last = name.substr(last_start, last_end - last_start);
            auto server_end = name.size();
            while (server_end > server_start && framework::unicode_whitespace(name[server_end - 1]))
                --server_end;
            return LslAvatarName{framework::utf8(first), framework::utf8(last),
                                 framework::utf8(name.substr(server_start, server_end - server_start))};
        }
    }
    auto last_end = name.size();
    while (last_end > last_start && framework::unicode_whitespace(name[last_end - 1]))
        --last_end;
    if (last_end == last_start)
        return {};
    return LslAvatarName{framework::utf8(first), framework::utf8(name.substr(last_start, last_end - last_start)), {}};
}

std::string username_from_name(std::string_view text) {
    auto name = framework::utf16_replacing(text);
    const auto first_end = std::find_if(name.begin(), name.end(), framework::unicode_whitespace);
    if (first_end != name.end()) {
        const auto second_end = std::find_if(first_end + 1, name.end(), framework::unicode_whitespace);
        if (std::u16string(first_end + 1, second_end) == u"Resident")
            name.erase(first_end, name.end());
        else
            std::replace(name.begin(), name.end(), u' ', u'.');
    }
    return framework::utf8(framework::invariant_lower_utf16(name));
}

std::u16string list_item_units(const LslValue &v);

std::u16string value_text_units(const LslValue &v) {
    if (const auto *box = std::get_if<std::shared_ptr<const LslObjectBox>>(&v))
        return value_text_units((*box)->value);
    if (auto text = raw_clr_text(v))
        return std::move(*text);
    if (std::holds_alternative<LslNullList>(v) || std::holds_alternative<LslNullObject>(v))
        null_string_reference();
    if (is_null_lsl_string(v))
        return {}; // String.Concat and list Soup treat a null String as empty.
    if (auto text = lsl_string_code_units(v))
        return std::move(*text);
    if (const auto *character = std::get_if<LslCharacter>(&v))
        return std::u16string(1, character->value);
    if (const auto *integer = value_get_if<std::int32_t>(&v))
        return framework::utf16_replacing(std::to_string(*integer));
    if (const auto *real = value_get_if<double>(&v))
        return framework::utf16_replacing(framework::format_invariant_double(*real, "0.000000"));
    if (const auto *vector = std::get_if<framework::Vector3d>(&v))
        return u"<" + value_text_units(vector->x) + u", " + value_text_units(vector->y) + u", " +
               value_text_units(vector->z) + u">";
    if (const auto *rotation = std::get_if<LslRotation>(&v))
        return u"<" + value_text_units(rotation->x) + u", " + value_text_units(rotation->y) + u", " +
               value_text_units(rotation->z) + u", " + value_text_units(rotation->w) + u">";
    const auto &list = list_reference(v);
    std::u16string text;
    for (const auto &item : list->items)
        text += list_item_units(item);
    return text;
}

std::u16string list_item_units(const LslValue &v) {
    if (const auto *box = std::get_if<std::shared_ptr<const LslObjectBox>>(&v))
        return list_item_units((*box)->value);
    if (const auto *real = std::get_if<double>(&v))
        return framework::utf16_replacing(framework::format_invariant_double(*real, ""));
    return value_text_units(v);
}

// Existing UTF8-only host and external adapters must fail explicitly rather
// than replacing an internal unpaired surrogate. Encoding APIs opt in below.
std::string value_text(const LslValue &v) {
    return required_text(make_lsl_string(value_text_units(v)));
}

std::string list_item_text(const LslValue &v) {
    return required_text(make_lsl_string(list_item_units(v)));
}

std::int32_t media_rule_integer(const LslValue &value) {
    if (value_holds<std::int32_t>(value) || value_holds<double>(value))
        return list_integer(value);
    if (const auto *text = value_get_if<std::string>(&value)) {
        constexpr auto whitespace = " \t\r\n\v\f";
        const auto begin = text->find_first_not_of(whitespace);
        if (begin != std::string::npos) {
            const auto end = text->find_last_not_of(whitespace) + 1;
            const auto *first = text->data() + begin;
            const auto *last = text->data() + end;
            if (*first == '+' && ++first != last && *first == '-')
                throw std::runtime_error("Expected an integer media rule");
            std::int32_t code;
            const auto parsed = std::from_chars(first, last, code);
            if (parsed.ec == std::errc{} && parsed.ptr == last)
                return code;
        }
    }
    throw std::runtime_error("Expected an integer media rule");
}

bool apply_media_rules(framework::ShapeMediaEntry &media, const LslList &rules) {
    for (std::size_t i = 1; i < rules.items.size(); i += 2) {
        const auto &value = rules.items[i];
        switch (media_rule_integer(rules.items[i - 1])) {
        case 0:
            media.enable_alternative_image = media_rule_integer(value) != 0;
            break;
        case 1:
            media.controls = media_rule_integer(value) != 0;
            break;
        case 2:
            media.current_url = framework::utf16_replacing(value_text(value));
            break;
        case 3:
            media.home_url = framework::utf16_replacing(value_text(value));
            break;
        case 4:
            media.auto_loop = media_rule_integer(value) != 0;
            break;
        case 5:
            media.auto_play = media_rule_integer(value) != 0;
            break;
        case 6:
            media.auto_scale = media_rule_integer(value) != 0;
            break;
        case 7:
            media.auto_zoom = media_rule_integer(value) != 0;
            break;
        case 8:
            media.interact_on_first_click = media_rule_integer(value) != 0;
            break;
        case 9:
            media.width = media_rule_integer(value);
            break;
        case 10:
            media.height = media_rule_integer(value);
            break;
        case 11:
            media.enable_whitelist = media_rule_integer(value) != 0;
            break;
        case 12: {
            const auto text = value_text(value);
            std::vector<std::optional<std::u16string>> urls;
            for (const auto item : std::string_view(text) | std::views::split(','))
                urls.emplace_back(
                    framework::utf16_replacing(framework::trim_utf8(std::string_view(item.begin(), item.end()))));
            if (urls.empty())
                urls.emplace_back(u"");
            media.whitelist = std::make_shared<framework::ShapeArray<std::optional<std::u16string>>>(std::move(urls));
            break;
        }
        case 13:
            media.interact_permissions = static_cast<std::uint8_t>(media_rule_integer(value));
            break;
        case 14:
            media.control_permissions = static_cast<std::uint8_t>(media_rule_integer(value));
            break;
        default:
            return false;
        }
    }
    return true;
}

std::string drawing_number(double value) {
    if (std::isnan(value))
        return "NaN";
    if (std::isinf(value))
        return std::signbit(value) ? "-Infinity" : "Infinity";

    // .NET's custom numeric format rounds the 15 significant decimal digits
    // of a double, then rounds again at the sixth fractional digit.
    char buffer[32];
    const auto encoded =
        std::to_chars(buffer, buffer + sizeof buffer, std::abs(value), std::chars_format::scientific, 14);
    const std::string scientific(buffer, encoded.ptr);
    const auto exponent_marker = scientific.find('e');
    auto digits = scientific.substr(0, exponent_marker);
    std::erase(digits, '.');
    const int keep = std::stoi(scientific.substr(exponent_marker + 1)) + 7;
    const auto retained = static_cast<std::size_t>(std::max(keep, 0));
    const bool round_up = keep >= 0 && retained < digits.size() && digits[retained] >= '5';
    digits.resize(retained, '0');
    if (round_up) {
        auto digit = digits.rbegin();
        while (digit != digits.rend() && *digit == '9') {
            *digit = '0';
            ++digit;
        }
        if (digit == digits.rend())
            digits.insert(0, 1, '1');
        else
            ++*digit;
    }
    if (digits.size() < 7)
        digits.insert(0, 7 - digits.size(), '0');
    digits.insert(digits.size() - 6, 1, '.');
    if (std::signbit(value))
        digits.insert(0, 1, '-');
    return digits;
}

std::string drawing_coordinate(const LslValue &value) {
    if (const auto *real = value_get_if<double>(&value))
        return drawing_number(*real);
    if (const auto *vector = std::get_if<framework::Vector3d>(&value))
        return "<" + drawing_number(vector->x) + ", " + drawing_number(vector->y) + ", " + drawing_number(vector->z) +
               ">";
    if (const auto *rotation = std::get_if<LslRotation>(&value))
        return "<" + drawing_number(rotation->x) + ", " + drawing_number(rotation->y) + ", " +
               drawing_number(rotation->z) + ", " + drawing_number(rotation->w) + ">";
    return value_text(value);
}

std::string json_marker(char16_t marker) {
    return framework::utf8(std::u16string_view(&marker, 1));
}

std::u16string quote_lsl_json(std::u16string_view input) {
    std::u16string result(1, '"');
    constexpr std::string_view hex = "0123456789ABCDEF";
    for (char16_t ch : input) {
        switch (ch) {
        case '"':
        case '\\':
        case '/':
            result += '\\';
            result += ch;
            break;
        case '\b':
            result += u"\\b";
            break;
        case '\t':
            result += u"\\t";
            break;
        case '\n':
            result += u"\\n";
            break;
        case '\f':
            result += u"\\f";
            break;
        case '\r':
            result += u"\\r";
            break;
        default:
            if (ch < 32) {
                result += u"\\u00";
                result += hex[ch >> 4];
                result += hex[ch & 15];
            } else
                result += ch;
        }
    }
    return result + u'"';
}

std::u16string lsl_json_item(const LslValue &item) {
    if (const auto *real = value_get_if<double>(&item)) {
        if (std::isinf(*real))
            return u"\"Inf\"";
        if (std::isnan(*real))
            return u"\"NaN\"";
        char buffer[64];
        const auto result = std::to_chars(buffer, buffer + sizeof buffer, *real);
        return framework::utf16_replacing(std::string_view(buffer, result.ptr));
    }
    if (value_holds<std::int32_t>(item))
        return value_text_units(item);
    if (const auto text = lsl_string_code_units(item)) {
        auto units = *text;
        std::u16string_view trimmed = units;
        while (!trimmed.empty() && framework::unicode_whitespace(trimmed.front()))
            trimmed.remove_prefix(1);
        while (!trimmed.empty() && framework::unicode_whitespace(trimmed.back()))
            trimmed.remove_suffix(1);
        const auto value = std::u16string(trimmed);
        if (!value.empty() && (value.front() == '{' || value.front() == '['))
            return value;
        if (value == u"true" || value == std::u16string(1, 0xFDD6))
            return u"true";
        if (value == u"false" || value == std::u16string(1, 0xFDD7))
            return u"false";
        if (value == u"null" || value == std::u16string(1, 0xFDD5))
            return u"null";
        return quote_lsl_json(value);
    }
    if (std::holds_alternative<std::shared_ptr<const LslList>>(item))
        return {};
    return quote_lsl_json(value_text_units(item));
}

std::string compute_hash(std::string_view source, std::string_view algorithm) {
    const auto *bytes = reinterpret_cast<const std::uint8_t *>(source.data());
    if (algorithm == "md5")
        return framework::md5(std::string(source));
    if (algorithm == "sha1")
        return framework::sha1_hex({bytes, source.size()});
    if (algorithm == "md5_sha1")
        return framework::md5(std::string(source)) + framework::sha1_hex({bytes, source.size()});
    if (algorithm == "sha224" || algorithm == "sha256")
        return framework::sha256_hex(source, algorithm == "sha224");
    if (algorithm == "sha384" || algorithm == "sha512")
        return framework::sha512_hex(source, algorithm == "sha384");
    return {};
}

std::string digest_bytes(std::string_view hex) {
    std::string result;
    const auto digit = [](char c) { return c <= '9' ? c - '0' : c - 'a' + 10; };
    for (std::size_t i = 0; i < hex.size(); i += 2)
        result += static_cast<char>(digit(hex[i]) * 16 + digit(hex[i + 1]));
    return result;
}

network::BinaryData decode_base64_units(std::u16string_view text) {
    // Convert.FromBase64String accepts ASCII Base64 and ASCII whitespace.
    // Validate code units before narrowing; surrogate replacement is not part
    // of this parser, and must not affect return-original XOR paths.
    std::string ascii;
    ascii.reserve(text.size());
    for (const auto unit : text) {
        if (unit > 0x7f)
            throw std::invalid_argument("Invalid Base64 character");
        ascii.push_back(static_cast<char>(unit));
    }
    network::Value encoded(std::move(ascii));
    encoded.kind = network::Value::Kind::Binary;
    return network::osd_binary(encoded);
}

template <class Value> decltype(auto) component_at(Value &value, std::size_t slot) {
    if (auto *rotation = std::get_if<LslRotation>(&value)) {
        switch (slot) {
        case 0:
            return (rotation->x);
        case 1:
            return (rotation->y);
        case 2:
            return (rotation->z);
        default:
            return (rotation->w);
        }
    }
    auto &vector = std::get<framework::Vector3d>(value);
    switch (slot) {
    case 0:
        return (vector.x);
    case 1:
        return (vector.y);
    default:
        return (vector.z);
    }
}

