                    if (left == right)
                        return e.op == Op::Minimum ? (std::signbit(left) ? left : right)
                                                   : (std::signbit(left) ? right : left);
                    return e.op == Op::Minimum ? std::min(left, right) : std::max(left, right);
                default:
                    return std::atan2(left, right);
