            framework::Uuid id;
            if (!host.npc_state || !framework::try_parse_sdk_uuid(key, id))
                return e.op == Expression::Op::NpcOwner ? LslValue{framework::Uuid{}.str()} : default_value(e.type);
            const auto npc = host.npc_state(id);
            if (e.op == Expression::Op::NpcOwner)
                return npc && !npc->owner.is_zero() ? npc->owner.str() : key;
            if (!npc || (!npc->owner.is_zero() && !context.owner.is_zero() && context.owner != npc->owner &&
                         context.owner != id))
                return default_value(e.type);
